window.ToyData.register("k12-math_9b_rjb.json","{\"book\":[9,\"下\",\"九下\",\"九年级下册\"],\"topics\":[[\"cnm_k9bcpt1\",\"math_9b_rjb_cpt1\",\"反比例函数\",\"概念\",\"形如 y = k/x (k 为常数且 k ≠ 0) 的函数称为反比例函数，其中 x 为自变量，y 为函数值，x 的取值范围为不等于 0 的一切实数。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"],[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{\"formula\":\"y = k/x\",\"aliases\":[\"inverse proportional function\"]}],[\"cnm_k9bcpt2\",\"math_9b_rjb_cpt2\",\"反比例函数的图象\",\"概念\",\"反比例函数 y = k/x 的图象由两条曲线组成，是双曲线。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"]],{\"aliases\":[\"双曲线图象\"]}],[\"cnm_k9bcpt3\",\"math_9b_rjb_cpt3\",\"反比例函数的性质（k>0）\",\"概念\",\"当 k>0 时，图象位于第一、第三象限，在每个象限内，y 随 x 的增大而减小。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"]],{}],[\"cnm_k9bcpt4\",\"math_9b_rjb_cpt4\",\"反比例函数的性质（k<0）\",\"概念\",\"当 k<0 时，图象位于第二、第四象限，在每个象限内，y 随 x 的增大而增大。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"]],{}],[\"cnm_k9bcpt5\",\"math_9b_rjb_cpt5\",\"反比例函数的对称性\",\"概念\",\"反比例函数 y = k/x 的图象关于直线 y = x 和 y = -x 对称。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"]],{}],[\"cnm_k9bskl1\",\"math_9b_rjb_skl1\",\"描点作图法\",\"技能\",\"通过列表取值计算若干对自变量和函数值的对应点，并在坐标系中描点后用平滑曲线连接，得到函数图象。\",[[\"26\",\"第二十六章 反比例函数\",\"第一节 反比例函数\"]],{}],[\"cnm_k9bcpt6\",\"math_9b_rjb_cpt6\",\"反比例关系\",\"概念\",\"两个量的乘积保持不变，其中一个量增大时，另一个量按比例减小。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{}],[\"cnm_k9bcpt7\",\"math_9b_rjb_cpt7\",\"杠杆原理\",\"概念\",\"阻力 × 阻力臂 = 动力 × 动力臂，当关系保持不变时动力与动力臂成反比例关系。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{\"formula\":\"F₁·l₁ = F₂·l₂\"}],[\"cnm_k9bcpt8\",\"math_9b_rjb_cpt8\",\"压强与受力面积的关系\",\"概念\",\"当压力一定时，压强与受力面积成反比例关系。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{\"formula\":\"p = F/S\"}],[\"cnm_k9bcpt9\",\"math_9b_rjb_cpt9\",\"气体压强与体积的关系\",\"概念\",\"温度一定时，气体压强与体积成反比例关系。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{}],[\"cnm_k9bcpt10\",\"math_9b_rjb_cpt10\",\"速度、功率与阻力的关系\",\"概念\",\"当功率一定时，行驶速度与所受阻力成反比例关系。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{\"formula\":\"v = P/F\"}],[\"cnm_k9bskl2\",\"math_9b_rjb_skl2\",\"建立反比例函数模型解决问题\",\"技能\",\"根据实际情景中两个量的关系，判断是否符合 x·y = k，并建立 y=k/x 型模型解决问题。\",[[\"26\",\"第二十六章 反比例函数\",\"第二节 实际问题与反比例函数\"]],{}],[\"cnm_k9bcpt11\",\"math_9b_rjb_cpt11\",\"相似图形\",\"概念\",\"形状相同的图形称为相似图形，一个图形可以看作由另一个通过放大或缩小得到。\",[[\"27\",\"第二十七章 相似\",\"第一节 图形的相似\"]],{\"examples\":[\"汽车与它的模型\",\"不同尺寸的足球\",\"同一底版洗出的不同尺寸的照片\",\"不同字号排出的相同文字\"],\"aliases\":[\"similar figures\"]}],[\"cnm_k9bcpt12\",\"math_9b_rjb_cpt12\",\"图形的放大与缩小\",\"概念\",\"将一个图形按比例放大或缩小得到另一个图形的过程，常出现在电影放映、复印等情境中。\",[[\"27\",\"第二十七章 相似\",\"第一节 图形的相似\"]],{\"examples\":[\"投影幕上的画面是胶片上图形的放大\",\"复印机将图形放大或缩小\"]}],[\"cnm_k9bskl3\",\"math_9b_rjb_skl3\",\"判断图形是否相似\",\"技能\",\"通过观察图形的形状是否相同，以及是否能够通过按比例放大或缩小获得，从而判断两个图形是否相似。\",[[\"27\",\"第二十七章 相似\",\"第一节 图形的相似\"]],{}],[\"cnm_k9bcpt13\",\"math_9b_rjb_cpt13\",\"相似三角形\",\"概念\",\"对应角相等、对应边成比例的两个三角形称为相似三角形，可记作 △ABC ∼ △A'B'C'。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{\"aliases\":[\"similar triangles\"]}],[\"cnm_269\",\"math_9b_rjb_cpt14\",\"平行线分线段成比例\",\"概念\",\"两条直线被一组平行线所截，所得的对应线段成比例。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt15\",\"math_9b_rjb_cpt15\",\"三角形相似判定：平行截线法\",\"概念\",\"平行于三角形一边的直线与其他两边相交，所构成的三角形与原三角形相似。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt16\",\"math_9b_rjb_cpt16\",\"三角形相似判定：三边成比例（SSS）\",\"概念\",\"如果两个三角形的三边成比例，则两个三角形相似。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt17\",\"math_9b_rjb_cpt17\",\"三角形相似判定：两边及夹角（SAS）\",\"概念\",\"如果两边成比例且夹角相等，则两个三角形相似。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt18\",\"math_9b_rjb_cpt18\",\"直角三角形相似判定（HL 比例）\",\"概念\",\"若两个直角三角形斜边和一条直角边成比例，则两个直角三角形相似。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt19\",\"math_9b_rjb_cpt19\",\"相似三角形的性质：对应线段成比例\",\"概念\",\"相似三角形对应的高、中线、角平分线等线段的比等于相似比。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt20\",\"math_9b_rjb_cpt20\",\"相似三角形的面积关系\",\"概念\",\"相似三角形的面积比等于相似比的平方。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt21\",\"math_9b_rjb_cpt21\",\"分形图形\",\"概念\",\"具有自相似性的图形，即局部与整体在一定程度上相似。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt22\",\"math_9b_rjb_cpt22\",\"自相似性\",\"概念\",\"图形的一部分与整体具有相似关系的性质。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bskl4\",\"math_9b_rjb_skl4\",\"利用相似三角形进行比例推理\",\"技能\",\"利用相似三角形的对应边比例关系求解未知长度、面积等量。\",[[\"27\",\"第二十七章 相似\",\"第二节 相似三角形\"]],{}],[\"cnm_k9bcpt23\",\"math_9b_rjb_cpt23\",\"正弦\",\"概念\",\"在直角三角形中，锐角的对边与斜边的比叫做这个锐角的正弦。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"]],{\"formula\":\"sin A = a/c\"}],[\"cnm_k9bcpt24\",\"math_9b_rjb_cpt24\",\"余弦\",\"概念\",\"在直角三角形中，锐角的邻边与斜边的比叫做这个锐角的余弦。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"]],{\"formula\":\"cos A = b/c\"}],[\"cnm_k9bcpt25\",\"math_9b_rjb_cpt25\",\"正切\",\"概念\",\"在直角三角形中，锐角的对边与邻边的比叫做这个锐角的正切。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"]],{\"formula\":\"tan A = a/b\"}],[\"cnm_k9bcpt26\",\"math_9b_rjb_cpt26\",\"锐角三角函数\",\"概念\",\"在直角三角形中，锐角的对边比斜边、邻边比斜边或对边比邻边的比值。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"],[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{\"formula\":\"sin A = a/c, cos A = b/c, tan A = a/b\"}],[\"cnm_k9bcpt27\",\"math_9b_rjb_cpt27\",\"特殊角三角函数值\",\"概念\",\"30°、45°、60°的正弦、余弦、正切具有固定值。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"]],{\"examples\":\"sin30°=1/2, cos60°=1/2, tan45°=1\"}],[\"cnm_k9bskl5\",\"math_9b_rjb_skl5\",\"利用相似三角形证明边比恒定\",\"技能\",\"通过判定直角三角形相似，证明锐角确定时对应边的比保持不变。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第一节 锐角三角函数\"]],{}],[\"cnm_278\",\"math_9b_rjb_cpt28\",\"解直角三角形\",\"概念\",\"已知直角三角形中的部分元素，利用边角关系求出其他未知元素的过程。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{\"examples\":[\"已知直角三角形的斜边和一条直角边，求锐角度数。\"]}],[\"cnm_k9bcpt29\",\"math_9b_rjb_cpt29\",\"直角三角形的五个元素\",\"概念\",\"除直角外的三条边与两个锐角，共五个元素。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{}],[\"cnm_k9bcpt30\",\"math_9b_rjb_cpt30\",\"两锐角互余\",\"概念\",\"直角三角形中两个锐角的和为90°。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{}],[\"cnm_k9bskl6\",\"math_9b_rjb_skl6\",\"实际问题的几何抽象\",\"技能\",\"将现实情境转化为直角三角形或几何模型以便计算。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{}],[\"cnm_k9bskl7\",\"math_9b_rjb_skl7\",\"化曲为直、化整为零思想\",\"技能\",\"将曲线或复杂形状分割为小段近似为直线，通过累加得到整体结果。\",[[\"28\",\"第二十八章 锐角三角函数\",\"第二节 解直角三角形及其应用\"]],{}],[\"cnm_k9bcpt31\",\"math_9b_rjb_cpt31\",\"投影\",\"概念\",\"用光线照射物体，在某个平面上形成的影子称为物体的投影。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"]],{\"examples\":[\"日光形成的影子\",\"灯光照射下的影子\"]}],[\"cnm_k9bcpt32\",\"math_9b_rjb_cpt32\",\"投影线\",\"概念\",\"照射物体并形成投影的光线称为投影线。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"]],{}],[\"cnm_k9bcpt33\",\"math_9b_rjb_cpt33\",\"投影面\",\"概念\",\"形成投影的所在平面称为投影面，如地面或墙壁。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"]],{}],[\"cnm_k9bcpt34\",\"math_9b_rjb_cpt34\",\"平行投影\",\"概念\",\"投影线彼此平行的投影方式，常用于得到立体图形的直观图。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"],[\"8\",\"第八章 立体几何初步\",\"第二节 立体图形的直观图\"]],{\"examples\":[\"太阳光形成的影子（日影）\"]}],[\"cnm_k9bcpt35\",\"math_9b_rjb_cpt35\",\"中心投影\",\"概念\",\"从同一点（点光源）发出的光线形成的投影。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"]],{\"examples\":[\"灯泡照射下形成的影子\"]}],[\"cnm_282\",\"math_9b_rjb_cpt36\",\"正投影\",\"概念\",\"投影线与投影面垂直的投影方式，是形成三视图的基础。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"],[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"],[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{}],[\"cnm_k9bskl8\",\"math_9b_rjb_skl8\",\"判断物体与投影面的空间位置关系\",\"技能\",\"能够辨别物体（线段、平面、立体）相对于投影面的平行、倾斜或垂直位置，并据此推断正投影的形状。\",[[\"29\",\"第二十九章 投影与视图\",\"第一节 投影\"]],{}],[\"cnm_k9bcpt37\",\"math_9b_rjb_cpt37\",\"视图\",\"概念\",\"从某一方向观察物体时所看到的平面图形，是物体在该方向光线下的正投影。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bcpt38\",\"math_9b_rjb_cpt38\",\"三视图\",\"概念\",\"用正投影方法分别从物体的前、上、左三个方向得到的三个视图，用以表示立体图形的形状和结构。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"],[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{\"examples\":[\"长对正，高平齐，宽相等\"],\"aliases\":[\"三面正投影图\"]}],[\"cnm_k9bcpt39\",\"math_9b_rjb_cpt39\",\"主视图\",\"概念\",\"在正面投影面上由前向后观察物体得到的视图，可表示物体的长和高。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bcpt40\",\"math_9b_rjb_cpt40\",\"俯视图\",\"概念\",\"在水平面上由上向下观察物体得到的视图，可表示物体的长和宽。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bcpt41\",\"math_9b_rjb_cpt41\",\"左视图\",\"概念\",\"在侧面上由左向右观察物体得到的视图，可表示物体的高和宽。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bcpt42\",\"math_9b_rjb_cpt42\",\"长对正、高平齐、宽相等\",\"概念\",\"绘制三视图时三个视图之间必须满足的对应关系：主视图与俯视图长对正，主视图与左视图高平齐，左视图与俯视图宽相等。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bskl9\",\"math_9b_rjb_skl9\",\"画三视图的方法\",\"技能\",\"确定主视图位置并绘制；在主视图正下方画俯视图并保持长对正；在主视图右侧画左视图并保持高平齐与宽相等；必要时绘制对称轴。\",[[\"29\",\"第二十九章 投影与视图\",\"第二节 三视图\"]],{}],[\"cnm_k9bcpt43\",\"math_9b_rjb_cpt43\",\"立体图形与平面图形的转化\",\"概念\",\"通过观察三视图或展开图，想象并构建对应的立体模型的过程，也包括由实物画出三视图或展开图。\",[[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{}],[\"cnm_k9bcpt44\",\"math_9b_rjb_cpt44\",\"中心投影与平行投影\",\"概念\",\"中心投影是投影线过同一点的投影方式；平行投影是投影线互相平行的投影方式。\",[[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{}],[\"cnm_k9bskl10\",\"math_9b_rjb_skl10\",\"由三视图想象立体图形\",\"技能\",\"综合前、上、侧三个视图的信息，通过空间想象能力推断立体图形的形状。\",[[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{}],[\"cnm_k9bskl11\",\"math_9b_rjb_skl11\",\"由展开图制作立体模型\",\"技能\",\"根据展开图的结构，将平面图形剪裁、折叠、粘贴成对应的立体图形。\",[[\"29\",\"第二十九章 投影与视图\",\"第三节 课题学习 制作立体模型\"]],{}]],\"dependencies\":[[\"cnm_k9bcpt1\",\"cnm_k9bcpt3\",\"一般地，当 k > 0 时，对于反比例函数 y = k/x...可以发现（性质）。\"],[\"cnm_k9bcpt1\",\"cnm_k9bcpt4\",\"一般地，当 k < 0 时，对于反比例函数 y = k/x...可以发现（性质）。\"],[\"cnm_k9bcpt2\",\"cnm_k9bcpt5\",\"一般地，反比例函数 y = k/x 的图象既关于直线 y = x 对称，又关于直线 y = -x 对称。\"],[\"cnm_k9bskl1\",\"cnm_k9bcpt2\",\"用“描点”的方法，画出反比例函数的图象。\"],[\"cnm_k9bcpt6\",\"cnm_k9bcpt1\",\"反比例函数刻画具有反比例关系的两个变量之间的对应关系。\"],[\"cnm_k9bcpt1\",\"cnm_k9bskl2\",\"用反比例函数刻画具有反比例关系的两个变量之间的对应关系。\"],[\"cnm_k9bcpt12\",\"cnm_k9bcpt11\",\"两个图形相似，其中一个图形可以看作由另一个图形放大或缩小得到。\"],[\"cnm_k9bcpt11\",\"cnm_k9bskl3\",\"我们把形状相同的图形叫做相似图形。\"],[\"cnm_269\",\"cnm_k9bcpt15\",\"平行于三角形一边的直线截其他两边…所得对应线段成比例。\"],[\"cnm_k9bskl5\",\"cnm_k9bcpt23\",\"“利用相似三角形可证明……对边与斜边的比是确定的”\"],[\"cnm_k9bskl5\",\"cnm_k9bcpt24\",\"类似正弦的情况可证明邻边与斜边的比确定\"],[\"cnm_k9bskl5\",\"cnm_k9bcpt25\",\"类似正弦的情况可证明对边与邻边的比确定\"],[\"cnm_k9bcpt26\",\"cnm_278\",\"利用这些关系，知道其中的两个元素…就可以求出其余三个未知元素。\"],[\"cnm_k9bcpt30\",\"cnm_278\",\"两个锐角的和为90°可用于求另一个锐角。\"],[\"cnm_k9bskl7\",\"cnm_k9bskl6\",\"化曲为直方法用于复杂情境的几何抽象。\"],[\"cnm_k9bcpt32\",\"cnm_k9bcpt34\",\"当光线是一组互相平行的射线……形成平行投影。\"],[\"cnm_k9bcpt32\",\"cnm_k9bcpt35\",\"由同一点发出的光线形成的投影叫做中心投影。\"],[\"cnm_k9bcpt33\",\"cnm_282\",\"投影线垂直照射投影面时形成正投影。\"],[\"cnm_k9bcpt37\",\"cnm_k9bcpt38\",\"本章中，我们只讨论三视图。\"],[\"cnm_k9bcpt39\",\"cnm_k9bcpt38\",\"三视图由主视图、俯视图和左视图组成。\"],[\"cnm_k9bskl9\",\"cnm_k9bcpt38\",\"画三视图时，三个视图都要放在正确的位置，并且注意长对正、高平齐、宽相等。\"],[\"cnm_282\",\"cnm_k9bcpt38\",\"在此基础上，进一步认识了三视图，学习了简单几何体三视图的画法。\"],[\"cnm_k9bcpt44\",\"cnm_282\",\"本章我们从生活实例出发，学习了中心投影和平行投影；研究了正投影的性质。\"],[\"cnm_k9bcpt34\",\"cnm_h108\",\"“利用平行投影，人们获得了画直观图的斜二测画法。”\"]],\"relations\":[[\"cnm_k9bcpt2\",\"cnm_k9bcpt1\",\"is_a\"],[\"cnm_k9bcpt1\",\"cnm_k9bcpt6\",\"is_a\"],[\"cnm_k9bcpt7\",\"cnm_k9bcpt6\",\"relates_to\"],[\"cnm_k9bcpt8\",\"cnm_k9bcpt6\",\"relates_to\"],[\"cnm_k9bcpt9\",\"cnm_k9bcpt6\",\"relates_to\"],[\"cnm_k9bcpt10\",\"cnm_k9bcpt6\",\"relates_to\"],[\"cnm_k9bcpt11\",\"cnm_k9bcpt12\",\"relates_to\"],[\"cnm_k9bcpt13\",\"cnm_k9bcpt19\",\"relates_to\"],[\"cnm_k9bcpt13\",\"cnm_k9bcpt20\",\"relates_to\"],[\"cnm_k9bcpt21\",\"cnm_k9bcpt22\",\"relates_to\"],[\"cnm_k9bcpt23\",\"cnm_k9bcpt26\",\"is_a\"],[\"cnm_k9bcpt24\",\"cnm_k9bcpt26\",\"is_a\"],[\"cnm_k9bcpt25\",\"cnm_k9bcpt26\",\"is_a\"],[\"cnm_k9bcpt23\",\"cnm_k9bcpt24\",\"relates_to\"],[\"cnm_k9bcpt23\",\"cnm_k9bcpt25\",\"relates_to\"],[\"cnm_k9bcpt26\",\"cnm_174\",\"relates_to\"],[\"cnm_k9bcpt29\",\"cnm_278\",\"is_a\"],[\"cnm_k9bcpt34\",\"cnm_k9bcpt31\",\"is_a\"],[\"cnm_k9bcpt35\",\"cnm_k9bcpt31\",\"is_a\"],[\"cnm_282\",\"cnm_k9bcpt34\",\"is_a\"],[\"cnm_k9bcpt34\",\"cnm_282\",\"relates_to\"],[\"cnm_k9bcpt39\",\"cnm_k9bcpt37\",\"is_a\"],[\"cnm_k9bcpt40\",\"cnm_k9bcpt37\",\"is_a\"],[\"cnm_k9bcpt41\",\"cnm_k9bcpt37\",\"is_a\"],[\"cnm_k9bcpt39\",\"cnm_k9bcpt40\",\"relates_to\"],[\"cnm_k9bcpt39\",\"cnm_k9bcpt41\",\"relates_to\"],[\"cnm_k9bcpt40\",\"cnm_k9bcpt41\",\"relates_to\"],[\"cnm_k9bcpt38\",\"cnm_k9bcpt43\",\"relates_to\"]]}");
